import BreaDSP
import Foundation
import Testing
@testable import BreaPresets

struct EqualizerAPOImporterTests {
    @Test func parsesAutoEqProfile() throws {
        let text = """
        # Generated by AutoEq
        Preamp: -6.4 dB
        Filter 1: ON LSC Fc 105 Hz Gain 6.5 dB Q 0.70
        Filter 2: ON PK Fc 3170 Hz Gain -2.4 dB Q 1.92
        Filter 3: OFF HSC Fc 10000 Hz Gain -3.1 dB Q 0.70
        Filter 4: ON PK Fc 1000 Hz Gain 2 dB BW Oct 1.0
        Filter 5: ON HP Fc 20 Hz
        """
        let result = try EqualizerAPOImporter.parse(text)
        let bands = result.settings.bands
        #expect(result.settings.pregainDB == -6.4)
        #expect(result.warnings.isEmpty)
        #expect(bands.count == 5)
        #expect(bands[0].type == .lowShelf && bands[0].frequency == 105 && bands[0].gainDB == 6.5 && bands[0].q == 0.70)
        #expect(bands[2].type == .highShelf && !bands[2].isEnabled)
        #expect(abs(bands[3].q - 1.414) < 0.01)   // 1 octave
        #expect(bands[4].type == .highPass && bands[4].q == 0.7071)
    }

    @Test func warnsAboutUnsupportedLines() throws {
        let text = """
        Device: Speakers
        Channel: L
        Preamp: -2 dB
        Filter: ON AP Fc 500 Hz Q 1
        """
        let result = try EqualizerAPOImporter.parse(text)
        #expect(result.settings.bands.isEmpty && result.settings.pregainDB == -2)
        #expect(result.warnings.count == 3)
    }

    @Test func rejectsUnrelatedText() {
        #expect(throws: EqualizerAPOImporter.ImportError.self) {
            try EqualizerAPOImporter.parse("hello: world\njust some notes")
        }
    }

    @Test func fitsGraphicEQToBands() throws {
        let reference = [
            EQBand(type: .peak, frequency: 120, gainDB: 5, q: 1.2),
            EQBand(type: .peak, frequency: 2_500, gainDB: -4, q: 2),
            EQBand(type: .highShelf, frequency: 9_000, gainDB: 3, q: 0.7071),
        ]
        let response = EQResponse(bands: reference, sampleRate: 48_000)
        let points = (0..<127).map { 20 * pow(1_000.0, Double($0) / 126) }
            .map { String(format: "%.1f %.2f", $0, response.decibels(at: $0) - 1.5) }
        let result = try EqualizerAPOImporter.parse("GraphicEQ: " + points.joined(separator: "; "))

        let fitted = EQResponse(bands: result.settings.bands, offsetDB: result.settings.pregainDB, sampleRate: 48_000)
        let worst = (0..<200).map { 20 * pow(1_000.0, Double($0) / 199) }
            .map { abs(fitted.decibels(at: $0) - (response.decibels(at: $0) - 1.5)) }
            .max() ?? .infinity
        #expect(worst < 0.5)
        #expect(result.settings.bands.count <= ProcessingChain.maxBands)
    }
}
